<?php
require __DIR__ . '/bootstrap.php'; require_login();
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';
 if($action==='create'){$title=trim($_POST['title']??'');$leadId=(int)($_POST['lead_id']??0);$due=$_POST['due_date']?:null;$priority=$_POST['priority']??'Medium';$notes=trim($_POST['notes']??'');if($title==='')$error='Task title is required.';elseif(!in_array($priority,['Low','Medium','High'],true))$error='Invalid priority.';else{$stmt=$pdo->prepare('INSERT INTO tasks (title,lead_id,assigned_to,due_date,priority,notes,created_by) VALUES (?,?,?,?,?,?,?)');$stmt->execute([$title,$leadId?:null,current_user()['id'],$due,$priority,$notes,current_user()['id']]);flash('Follow-up task created.');header('Location: tasks.php');exit;}}
 if($action==='complete'){$taskId=(int)($_POST['task_id']??0);$stmt=$pdo->prepare("UPDATE tasks SET status='Completed' WHERE id=?");$stmt->execute([$taskId]);flash('Task marked as completed.');header('Location: tasks.php');exit;}
}
$leads=$pdo->query('SELECT id,full_name FROM leads ORDER BY full_name LIMIT 1000')->fetchAll();$tasks=$pdo->query("SELECT t.*,l.full_name,u.name assigned_name FROM tasks t LEFT JOIN leads l ON l.id=t.lead_id LEFT JOIN users u ON u.id=t.assigned_to ORDER BY (t.status='Open') DESC,t.due_date IS NULL,t.due_date,t.created_at DESC LIMIT 300")->fetchAll();$flash=get_flash();require __DIR__.'/partials/header.php';
?>
<div class="page-heading"><div><p class="eyebrow">SALES PRODUCTIVITY</p><h1>Follow-ups & tasks</h1><p class="muted">Keep every next step visible and accountable.</p></div></div><?php if($flash):?><div class="alert <?=h($flash['type'])?>"><?=h($flash['message'])?></div><?php endif;?><?php if($error):?><div class="alert error"><?=h($error)?></div><?php endif;?>
<div class="content-grid tasks-layout"><section class="panel"><div class="panel-heading"><div><h2>Task list</h2><p class="muted">Open and completed follow-ups</p></div></div><div class="task-table"><?php if(!$tasks):?><div class="empty">No tasks created yet.</div><?php endif;?><?php foreach($tasks as $t):?><div class="task-list-row"><div class="task-main"><span class="task-state <?=$t['status']==='Completed'?'done':''?>"><?=$t['status']==='Completed'?'✓':'○'?></span><div><strong class="<?=$t['status']==='Completed'?'completed-text':''?>"><?=h($t['title'])?></strong><small><?=h($t['full_name']??'No linked lead')?> · Due <?=h($t['due_date']?:'not scheduled')?></small><?php if($t['notes']):?><p><?=h($t['notes'])?></p><?php endif;?></div></div><div class="task-actions"><span class="priority priority-<?=h(strtolower($t['priority']))?>"><?=h($t['priority'])?></span><?php if($t['status']==='Open'):?><form method="post"><input type="hidden" name="csrf_token" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="complete"><input type="hidden" name="task_id" value="<?=(int)$t['id']?>"><button class="small-btn" title="Mark completed">✓</button></form><?php endif;?></div></div><?php endforeach;?></div></section>
<section class="panel"><div class="panel-heading"><div><h2>Create task</h2><p class="muted">Schedule a follow-up</p></div></div><form method="post" class="form-stack"><input type="hidden" name="csrf_token" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="create"><label>Task title *<input name="title" required maxlength="180" placeholder="Call customer about documents"></label><label>Link to lead<select name="lead_id"><option value="0">No linked lead</option><?php foreach($leads as $l):?><option value="<?=(int)$l['id']?>">#<?=$l['id']?> · <?=h($l['full_name'])?></option><?php endforeach;?></select></label><label>Due date<input type="date" name="due_date" min="<?=date('Y-m-d')?>"></label><label>Priority<select name="priority"><option>Medium</option><option>High</option><option>Low</option></select></label><label>Notes<textarea name="notes" rows="3" maxlength="3000"></textarea></label><button class="btn primary full">Create task</button></form></section></div>
<?php require __DIR__.'/partials/footer.php';?>
